SELECT memberid, membername, type, branchid
FROM ttokssaemdb.member
WHERE memberid = #{memberid}
  AND branchid = #{branchid}

SELECT member.memberid, member.membername
FROM ttokssaemdb.parents parents
INNER JOIN ttokssaemdb.member member ON member.memberid = parents.memberid
WHERE parents.parentid = #{parentid}
  AND member.memberid = #{targetid}
  AND member.branchid = #{branchid}
  AND member.type = 'S'

SELECT memberid, membername
FROM ttokssaemdb.member
WHERE memberid = #{memberid}
  AND branchid = #{branchid}
  AND type = 'S'

SELECT COUNT(*) totcnt
FROM ttokssaemdb.blackmark
WHERE memberid = #{memberid}
  AND branchid = #{branchid}
